package com.familos.homepulse;

import android.os.SystemClock;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;
import java.time.ZoneId;
import java.util.UUID;

/** Offline session state and explicitly estimated MET energy; no inferred targets. */
public final class Workout {
    private final Store store;
    public Workout(Store store) { this.store=store; }
    public JSONObject current() { return store.currentSession(); }
    public JSONArray sessions() { return store.sessions(); }
    static double now() { return System.currentTimeMillis()/1000.0; }
    static double elapsed(JSONObject session) { if(session==null)return 0;double value=Math.max(0,session.optDouble("active_seconds",0));if("active".equals(session.optString("status"))){double wall=now()-session.optDouble("running_since",now());long start=session.optLong("running_elapsed_ms",-1),boot=session.optLong("boot_epoch_ms",-1);long estimatedBoot=System.currentTimeMillis()-SystemClock.elapsedRealtime();if(start>=0&&boot>=0&&Math.abs(boot-estimatedBoot)<60000&&SystemClock.elapsedRealtime()>=start)wall=(SystemClock.elapsedRealtime()-start)/1000.0;value+=Math.max(0,wall);}return value; }
    public double elapsedSeconds() { return elapsed(current()); }
    private static void running(JSONObject value)throws JSONException { value.put("running_since",now());value.put("running_elapsed_ms",SystemClock.elapsedRealtime());value.put("boot_epoch_ms",System.currentTimeMillis()-SystemClock.elapsedRealtime());value.put("status","active");value.put("state","running"); }
    private JSONObject commit(JSONObject session,String action) { double elapsed=elapsed(session);JSONObject payload=Store.object("action",action,"session_id",session.optString("remote_id",session.optString("id")),"activity_name",session.optString("activity_name","Allenamento"),"active_seconds",elapsed,"auto_detected",session.optBoolean("auto_detected",false),"provisional",session.optBoolean("provisional",false),"source",session.optString("source","manual"),"config_snapshot",Store.copy(session.optJSONObject("config")),"profile_snapshot",Store.copy(session.optJSONObject("profile")),"phase_index",position(elapsed,session.optJSONObject("config")).optInt("index",0));store.commitWorkout(session,payload);return Store.copy(session); }
    public synchronized JSONObject start(String activity) { return start(activity,false); }
    public synchronized JSONObject start(String activity,boolean automatic) { if(current()!=null){JSONObject value=current();if(!automatic&&value.optBoolean("provisional"))return confirm(activity);return value;}JSONObject settings=store.settings();validateSettings(settings);String name=name(activity);String id=UUID.randomUUID().toString();JSONObject session=Store.object("id",id,"remote_id",id,"activity_name",name,"started_at",now(),"active_seconds",0,"config",Store.copy(settings.optJSONObject("config")),"profile",Store.copy(settings.optJSONObject("profile")),"auto_detected",automatic,"provisional",automatic,"source",automatic?"geofence_heart_rate":"manual");try{running(session);}catch(JSONException e){throw Store.failure(e);}return commit(session,"started"); }
    public synchronized JSONObject pause() { JSONObject value=current();if(value==null||!"active".equals(value.optString("status")))return value;try{value.put("active_seconds",elapsed(value));value.put("running_since",JSONObject.NULL);value.put("running_elapsed_ms",JSONObject.NULL);value.put("status","paused");value.put("state","paused");}catch(JSONException e){throw Store.failure(e);}return commit(value,"paused"); }
    public synchronized JSONObject resume() { JSONObject value=current();if(value==null||!"paused".equals(value.optString("status")))return value;try{running(value);}catch(JSONException e){throw Store.failure(e);}return commit(value,"resumed"); }
    public synchronized JSONObject end() { return finish(false); }
    public synchronized JSONObject falseDetection() { return finish(true); }
    private JSONObject finish(boolean rejected) { JSONObject value=current();if(value==null)return null;try{value.put("active_seconds",elapsed(value));value.put("running_since",JSONObject.NULL);value.put("running_elapsed_ms",JSONObject.NULL);value.put("ended_at",now());value.put("status",rejected?"rejected":"completed");value.put("state",rejected?"false_detection":"ended");value.put("provisional",false);}catch(JSONException e){throw Store.failure(e);}return commit(value,rejected?"false_detection":"ended"); }
    public synchronized JSONObject updateActivity(String activity) { JSONObject value=current();if(value==null)return null;try{value.put("activity_name",name(activity));value.put("provisional",false);}catch(JSONException e){throw Store.failure(e);}return commit(value,"activity_updated"); }
    public synchronized JSONObject confirm(String activity) { JSONObject value=current();if(value==null)return null;try{value.put("activity_name",name(activity));value.put("provisional",false);}catch(JSONException e){throw Store.failure(e);}return commit(value,"confirmed"); }
    private static String name(String value) { String name=value==null?"":value.trim();if(name.isEmpty())name="Allenamento";if(name.length()>80)throw new IllegalArgumentException("Nome attività: massimo 80 caratteri");return name; }
    static JSONArray phases(JSONObject config) { JSONObject cfg=config==null?new JSONObject():config;JSONArray plan=cfg.optJSONArray("plan");if(plan!=null&&plan.length()>0)return Store.copy(plan);JSONArray result=new JSONArray();result.put(Store.object("name","Lavoro","duration",cfg.optInt("work",40)));if(cfg.optInt("rest",20)>0)result.put(Store.object("name","Recupero","duration",cfg.optInt("rest",20)));return result; }
    public static double total(JSONObject config) { JSONArray phases=phases(config);double cycle=0;for(int i=0;i<phases.length();i++)cycle+=phases.optJSONObject(i).optDouble("duration",0);return cycle*(config==null?8:config.optInt("rounds",8)); }
    public JSONObject position() { JSONObject value=current();return value==null?Store.object("name","Nessuna sessione","remaining",0,"round",0,"index",0,"complete",true,"total",0):position(elapsed(value),value.optJSONObject("config")); }
    public static JSONObject position(double elapsed,JSONObject config) { JSONArray phases=phases(config);double cycle=0;for(int i=0;i<phases.length();i++)cycle+=phases.optJSONObject(i).optDouble("duration",0);double total=total(config);if(cycle<=0||elapsed>=total)return Store.object("name","Completato","round",config==null?8:config.optInt("rounds",8),"remaining",0,"index",Math.max(0,phases.length()-1),"complete",true,"total",total,"elapsed",elapsed,"target_min",null,"target_max",null,"met",null);int round=(int)(Math.max(0,elapsed)/cycle)+1;double at=Math.max(0,elapsed)%cycle;for(int i=0;i<phases.length();i++){JSONObject phase=phases.optJSONObject(i);double duration=phase.optDouble("duration",0);if(at<duration)return Store.object("name",phase.optString("name","Fase"),"round",round,"remaining",(int)Math.ceil(duration-at),"index",i,"complete",false,"total",total,"elapsed",elapsed,"target_min",phase.opt("target_min"),"target_max",phase.opt("target_max"),"met",phase.opt("met"));at-=duration;}throw new IllegalStateException("Scheda non valida"); }
    public JSONObject energy() { JSONObject value=current();return value==null?Store.object("gross",null,"net",null,"estimated",false,"estimated_seconds",0,"unestimated_seconds",0,"coverage",0):energy(elapsed(value),value.optJSONObject("config"),value.optJSONObject("profile")); }
    public static JSONObject energy(double elapsed,JSONObject config,JSONObject profile) { double duration=Math.max(0,elapsed),weight=profile==null?Double.NaN:profile.optDouble("weight_kg",Double.NaN),gross=0,net=0,estimated=0;if(Double.isFinite(weight)&&weight>=30&&weight<=350){JSONArray phases=phases(config);double cycle=0;for(int i=0;i<phases.length();i++)cycle+=phases.optJSONObject(i).optDouble("duration",0);if(cycle>0){double within=Math.min(duration,total(config));int rounds=(int)(within/cycle);double remainder=within-rounds*cycle;for(int i=0;i<phases.length();i++){JSONObject phase=phases.optJSONObject(i);double seconds=phase.optDouble("duration",0);double used=rounds*seconds+Math.min(Math.max(0,remainder),seconds);remainder=Math.max(0,remainder-seconds);double met=phase.optDouble("met",Double.NaN);if(Double.isFinite(met)&&met>=1&&met<=20){estimated+=used;gross+=used*met*3.5*weight/12000.0;net+=used*(met-1)*3.5*weight/12000.0;}}}}return Store.object("gross",estimated>0?gross:null,"net",estimated>0?net:null,"estimated",estimated>0,"estimated_seconds",estimated,"unestimated_seconds",Math.max(0,duration-estimated),"coverage",duration>0?estimated/duration:0,"method","MET convenzionali: stima, non calorimetria"); }
    private static void number(JSONObject object,String key,double low,double high,boolean integer,boolean optional) { Object raw=object.opt(key);if(raw==null||raw==JSONObject.NULL){if(optional)return;throw new IllegalArgumentException("Campo richiesto: "+key);}if(!(raw instanceof Number))throw new IllegalArgumentException("Valore numerico non valido: "+key);double value=((Number)raw).doubleValue();if(!Double.isFinite(value)||value<low||value>high||(integer&&value!=Math.rint(value)))throw new IllegalArgumentException("Valore fuori intervallo: "+key); }
    private static void optionalText(JSONObject object,String key,int limit,boolean required) { Object value=object.opt(key);if(value==null||value==JSONObject.NULL){if(required)throw new IllegalArgumentException("Testo richiesto: "+key);return;}if(!(value instanceof String)||((String)value).length()>limit||(required&&((String)value).trim().isEmpty()))throw new IllegalArgumentException("Testo non valido: "+key); }
    private static void validateDetection(JSONObject settings) { if(!settings.has("auto_detection"))return;JSONObject auto=settings.optJSONObject("auto_detection");if(auto==null)throw new IllegalArgumentException("Rilevamento automatico non valido");if(auto.has("enabled")&&!(auto.opt("enabled") instanceof Boolean))throw new IllegalArgumentException("Rilevamento automatico non valido");number(auto,"heart_rate_delta_bpm",1,100,false,true);number(auto,"sustain_seconds",5,600,false,true);number(auto,"cooldown_seconds",60,86400,false,true);if(auto.has("gym")){JSONObject gym=auto.optJSONObject("gym");if(gym==null)throw new IllegalArgumentException("Palestra non valida");for(String field:new String[]{"id","name","address"})if(gym.has(field))optionalText(gym,field,300,true);number(gym,"latitude",-90,90,false,true);number(gym,"longitude",-180,180,false,true);number(gym,"radius_m",25,2000,false,true);} }
    public static void validateSettings(JSONObject settings) { JSONObject profile=settings.optJSONObject("profile"),config=settings.optJSONObject("config");if(profile==null||config==null)throw new IllegalArgumentException("Profilo e scheda richiesti");String[] fields={"weight_kg","body_fat_pct","height_cm","age","reported_lean_pct","reported_retention_pct","resting_hr"};double[] low={30,2,100,18,2,0,20},high={350,65,250,100,98,100,200};for(int i=0;i<fields.length;i++)number(profile,fields[i],low[i],high[i],fields[i].equals("age"),true);for(String key:new String[]{"goal","composition_source"})optionalText(profile,key,200,false);
        number(config,"work",5,3600,true,false);number(config,"rest",0,3600,true,false);number(config,"rounds",1,100,true,false);number(config,"hrmax",80,240,true,true);number(config,"activity_id",0,65535,true,true);optionalText(config,"activity_name",80,false);if(config.has("plan")&&!(config.opt("plan") instanceof JSONArray))throw new IllegalArgumentException("Scheda non valida");JSONArray phases=phases(config);JSONArray plan=config.optJSONArray("plan");if(plan!=null&&plan.length()>40)throw new IllegalArgumentException("Massimo 40 fasi");for(int i=0;i<phases.length();i++){JSONObject phase=phases.optJSONObject(i);if(phase==null||phase.optString("name","").trim().isEmpty()||phase.optString("name").length()>80)throw new IllegalArgumentException("Nome fase richiesto");number(phase,"duration",5,7200,true,false);number(phase,"met",1,20,false,true);number(phase,"target_min",40,240,true,true);number(phase,"target_max",40,240,true,true);boolean a=phase.has("target_min")&&!phase.isNull("target_min"),b=phase.has("target_max")&&!phase.isNull("target_max");if(a!=b||(a&&phase.optInt("target_min")>=phase.optInt("target_max")))throw new IllegalArgumentException("Intervallo FC non valido");}if(total(config)>86400)throw new IllegalArgumentException("Scheda oltre 24 ore");JSONArray weekly=settings.optJSONArray("weekly_schedule");if(settings.has("weekly_schedule")&&weekly==null)throw new IllegalArgumentException("Calendario non valido");validateDetection(settings);if(weekly!=null){if(weekly.length()>100)throw new IllegalArgumentException("Calendario troppo lungo");for(int i=0;i<weekly.length();i++){JSONObject rule=weekly.optJSONObject(i);if(rule==null)throw new IllegalArgumentException("Calendario non valido");number(rule,"weekday",1,7,true,false);String start=rule.optString("start"),end=rule.optString("end");if(!start.matches("(?:[01][0-9]|2[0-3]):[0-5][0-9]")||!end.matches("(?:[01][0-9]|2[0-3]):[0-5][0-9]")||start.compareTo(end)>=0)throw new IllegalArgumentException("Orari settimanali non validi");try{ZoneId.of(rule.optString("timezone","Europe/Rome"));}catch(Exception e){throw new IllegalArgumentException("Fuso orario non valido");}}} }
}
